// 纯合同边界组件不冒完整雇用世界；实际Common头序与phase均使用原模型。
#include "resident/domains/commerce/private_shop_staff_exclusion.hpp"
#include "resident/domains/commerce/private_shop.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;void check(bool p,const char* s){++checks;if(!p)throw std::runtime_error(s);}
StableId fact(CommonStore& c,const StableId& prefix,const StableId& kind,const StableId& domain){auto id=c.next_id(prefix);check(id.ok,"actual fact ID");check(c.append_fact({id.value,kind,domain}).ok,"actual fact append");return id.value;}
void responsibility_boundary(){auto catalog=std::make_shared<CommonCatalog>();CommonStore common{CommonState{},catalog};common.state().identity.world_id[0]=1;ActorRecord actor;actor.id="worker";common.state().actors.insert(actor.id,actor);PrivateShopState shops;PrivateShopRecord shop;shop.id="fixture.shop";shops.shops.insert(shop.id,shop);PrivateShopWorkerCommitmentAccess read(common,shops);
 const auto early=fact(common,"estate","estate_management","estate");check(guard_private_shop_worker_commitment(common,nullptr,"worker",early,0).ok,"old profile unchanged");auto id=fact(common,"private_shop_staff","private_shop_staff_accepted",private_shop_module);PrivateShopStaffContract contract;contract.id=id;contract.terms.shop_id=shop.id;contract.terms.worker_actor_id="worker";contract.accepted_tick=0;contract.through_tick=6;shops.staff.contracts.insert(id,contract);
 check(!guard_private_shop_worker_commitment(common,nullptr,"worker").ok,"missing enabled source rejected");check(!guard_private_shop_worker_commitment(common,&read,"worker").ok,"current shop employee committed");check(guard_private_shop_worker_commitment(common,&read,"worker",early,0).ok,"earlier actual management remains valid");const auto during=fact(common,"estate_employment_decision","estate_employment_decided","estate_employment");check(!guard_private_shop_worker_commitment(common,&read,"worker",during,0).ok,"later estate acceptance cannot overlap");auto ended=fact(common,"private_shop_staff_decision","private_shop_staff_ended",private_shop_module);shops.staff.contracts.find(id)->status="left";shops.staff.contracts.find(id)->terminal_fact_id=ended;shops.staff.decisions.insert(ended,{ended,id,"worker","left",0});check(guard_private_shop_worker_commitment(common,&read,"worker").ok,"current released worker allowed");check(!guard_private_shop_worker_commitment(common,&read,"worker",during,0).ok,"later release cannot clear past overlap");const auto after=fact(common,"estate","estate_management","estate");check(guard_private_shop_worker_commitment(common,&read,"worker",after,0).ok,"real release before new assignment");check(!guard_private_shop_worker_commitment(common,&read,"worker",after,1).ok,"cold cannot borrow future clock");DynamicStepInput phase{0,1};PrivateShopWorkerCommitmentAccess phase_read(common,shops,&phase);check(guard_private_shop_worker_commitment(common,&phase_read,"worker",after,1,&phase).ok,"explicit original phase accepts to boundary");DynamicStepInput bad{0,2};PrivateShopWorkerCommitmentAccess bad_read(common,shops,&bad);check(!bad_read.private_shop_worker_commitments("worker").ok,"future jump rejected");shops.staff.decisions={};check(!read.private_shop_worker_commitments("worker").ok,"missing permanent termination rejects");}
}
int main(){try{responsibility_boundary();std::cout<<checks<<"/0 private shop estate exclusion checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
